// DESHACER en la web las uniones corregidas del 14-oct (costo, origen y comisión de 15 productos).
// ssh -i ~/.ssh/casa-viva-github-actions -p 65002 u824654880@88.223.85.72 'cd ~/domains/casaviva.company/public_html && wp eval-file - && wp litespeed-purge all' < docs/nexo-business/precios/2026-10-14/deshacer-uniones-web.php
$b = json_decode( base64_decode( '' ), true );
foreach ( $b as $id => $o ) {
	$p = wc_get_product( (int) $id ); if ( ! $p ) { continue; }
	if ( '' === (string) $o['cost'] ) { $p->delete_meta_data( '_cvd_cost_usd' ); $p->delete_meta_data( '_cvd_cost_source' ); } else { $p->update_meta_data( '_cvd_cost_usd', $o['cost'] ); $p->update_meta_data( '_cvd_cost_source', $o['src'] ); }
	if ( '' === (string) $o['ctype'] ) { $p->delete_meta_data( '_cvd_commission_type' ); $p->delete_meta_data( '_cvd_commission_value' ); } else { $p->update_meta_data( '_cvd_commission_type', $o['ctype'] ); $p->update_meta_data( '_cvd_commission_value', $o['cval'] ); }
	$p->save();
}
echo "Deshecho: " . count( $b ) . " productos\n";
